import React from 'react'
import {DashboardBackground, BodyContainer,TitleContainer} from './styles';

import Header from '../../components/Header';
import Card from '../../components/Card';
import Property from '../../components/Property';
import Input from '../../components/Input';

const Dashboard = ()=>{

    
    return(
       <DashboardBackground>
           <Header />
           <BodyContainer>
               <TitleContainer>
       
                       <h2>Register</h2>
                       <Card width="20px">
                       <p>+</p>
                   </Card>
                   <Input />

                   </TitleContainer>
                   <Card width='100%' marginTop='20px' >
                    <Property />
                    </Card>
                    <Card width='100%' marginTop='20px' >
                    <Property />
                    </Card>

               
               
           </BodyContainer>

       </DashboardBackground>
            
        
    )
}

export default Dashboard;
